using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

public sealed class EvaluationConfig
{
    public List<Scenario> Scenarios { get; set; } = [];
}

public sealed class Scenario
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<Turn> Turns { get; set; } = [];
    public List<string> Evaluators { get; set; } = [];
}

public sealed class Turn
{
    public string Prompt { get; set; } = string.Empty;
}

public static class ScenarioLoader
{
    public static EvaluationConfig Load(string path = "evaluation.yml")
    {
        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(UnderscoredNamingConvention.Instance)
            .Build();
        return deserializer.Deserialize<EvaluationConfig>(yaml);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder? _appHost;
    private IChatClient? _chatClient;
    private ReportingConfiguration? _reportingConfig;

    public async Task InitializeAsync()
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var app = await _appHost.StartAsync();
        _chatClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"));
    }

    public async Task DisposeAsync()
    {
        if (_appHost is IAsyncDisposable disposable)
            await disposable.DisposeAsync();
    }

    [Fact]
    public async Task EvaluateAllScenarios()
    {
        var config = ScenarioLoader.Load();
        var results = new List<(string Scenario, EvaluationResult Result)>();

        foreach (var scenario in config.Scenarios)
        {
            var result = await RunScenarioAsync(scenario);
            results.Add((scenario.Name, result));
        }

        foreach (var (name, result) in results)
        {
            foreach (var metric in result.Metrics)
            {
                Assert.True(
                    metric.Value is NumericMetricValue numeric && numeric.Value >= 3.0,
                    $"Scenario '{name}' failed metric '{metric.Key}' with value {metric.Value}");
            }
        }
    }

    [Theory]
    [MemberData(nameof(GetScenarios))]
    public async Task EvaluateScenario(string scenarioName)
    {
        var config = ScenarioLoader.Load();
        var scenario = config.Scenarios.First(s => s.Name == scenarioName);

        var result = await RunScenarioAsync(scenario);

        foreach (var metric in result.Metrics)
        {
            Assert.True(
                metric.Value is NumericMetricValue numeric && numeric.Value >= 3.0,
                $"Metric '{metric.Key}' scored below threshold with value {metric.Value}");
        }
    }

    public static TheoryData<string> GetScenarios()
    {
        var config = ScenarioLoader.Load();
        var data = new TheoryData<string>();
        foreach (var scenario in config.Scenarios)
            data.Add(scenario.Name);
        return data;
    }

    private async Task<EvaluationResult> RunScenarioAsync(Scenario scenario)
    {
        var chatHistory = new List<ChatMessage>();
        ChatMessage? lastResponse = null;

        foreach (var turn in scenario.Turns)
        {
            chatHistory.Add(new ChatMessage(ChatRole.User, turn.Prompt));
            var response = await _chatClient!.GetResponseAsync(chatHistory);
            lastResponse = new ChatMessage(ChatRole.Assistant, response.Text);
            chatHistory.Add(lastResponse);
        }

        var evaluators = CreateEvaluators(scenario.Evaluators);
        var evalResult = await EvaluateResponseAsync(chatHistory, evaluators);
        return evalResult;
    }

    private static IList<IEvaluator> CreateEvaluators(List<string> evaluatorNames)
    {
        var evaluators = new List<IEvaluator>();
        foreach (var name in evaluatorNames)
        {
            IEvaluator evaluator = name.ToLowerInvariant() switch
            {
                "relevance" => new RelevanceEvaluator(),
                "coherence" => new CoherenceEvaluator(),
                "fluency" => new FluencyEvaluator(),
                "groundedness" => new GroundednessEvaluator(),
                _ => throw new ArgumentException($"Unknown evaluator: {name}")
            };
            evaluators.Add(evaluator);
        }
        return evaluators;
    }

    private static async Task<EvaluationResult> EvaluateResponseAsync(
        List<ChatMessage> chatHistory,
        IList<IEvaluator> evaluators)
    {
        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(chatHistory);
            foreach (var metric in evalResult.Metrics)
                result.Metrics.Add(metric.Key, metric.Value);
        }
        return result;
    }
}

